export const SYNOLOGY_HARDWARE = Object.freeze(Object.fromEntries(rows.map(([model,cpu,cores,threads,arch,memory,bays]) => [model, Object.freeze({
  model, family: model.match(/^(DS|RS|FS|SA|HD|DVA|UC|PAS)/)?.[1] || 'unknown',
  cpu: cpu ? { model: cpu, cpuCount: /x2\b/i.test(cpu) ? 2 : 1, coresPerCpu: cores, threadsPerCpu: threads, cores: cores * (/x2\b/i.test(cpu) ? 2 : 1), threads: threads * (/x2\b/i.test(cpu) ? 2 : 1), architecture: arch } : null,
  memory: memory ? { type: memory, installedCapacityGB: null, slots: null, maximumGB: null } : null,
  storage: { internalBays: bays, m2Slots: ({'DS723+':2,'DS725+':2,'DS925+':2,'DS1525+':2,'DS1825+':2,'DS1525neo+':2,'DS1825neo+':2,'DS725neo+':2,'DS925neo+':2,'DS923+':2,'DS1522+':2,'DS1821+':2,'DS1823xs+':2,'DS920+':2,'DS720+':2,'DS420+':2})[model] ?? null, m2FormFactor: null, expansionMaxBays: null },
  provenance: { cpu: SYNOLOGY_SOURCES.cpu, bays: SYNOLOGY_SOURCES.products, verifiedAt: '2026-11-18', confidence: cpu && bays ? 'official-source-reference; per-model field audit recommended' : 'partial; do not infer missing fields' },
})])));

export function normalizeSynologyModel(input = '') {
  const s = String(input).trim().replace(/^Synology\s+/i, '').replace(/\s+/g, '');
  const upper = s.toUpperCase();
  return Object.keys(SYNOLOGY_HARDWARE).find(k => k.toUpperCase() === upper) || null;
}

export const SYNOLOGY_MODEL_LIST = Object.keys(SYNOLOGY_HARDWARE).sort();
